"""Write the required results report from executed receipts, not projected outcomes."""
import hashlib
import json
from pathlib import Path
import statistics
import re
import zipfile

ROOT=Path(__file__).resolve().parents[1];R=ROOT/'reports/phase7'
def read(name):return json.loads((R/name).read_text())
def sha(p):return hashlib.sha256(p.read_bytes()).hexdigest()
def median(runs,k):return statistics.median(x[k] for x in runs)

def run():
    a=read('EXACT_SUPPORT_AUDIT.json');o=read('EXACT_INDEPENDENT_VALIDATION.json');q=read('QUALIFICATION_SENSITIVITY.json');m=read('L2_EXACT_DOWNLOAD_MANIFEST.json');p=read('PRESERVATION.json');v=read('VISUAL_AND_PERFORMANCE.json');memory=read('L2_RUNTIME_MEMORY.json')
    tests=read('final-full-browser-results.json')['stats'];assert tests['unexpected']==0 and tests['expected']==96
    with zipfile.ZipFile(ROOT/'data/backups/phase7-before.zip') as z:before=json.loads(z.read('SNAPSHOT_SHA256.json'))
    new_sources=sorted(x.relative_to(ROOT).as_posix() for folder in ['src','science','scripts','tests'] for x in (ROOT/folder).rglob('*') if x.is_file() and '__pycache__' not in x.parts and x.relative_to(ROOT).as_posix() not in before)
    text=['# Phase 7 — metadata-first bridge execution',
      'Completed 14 November 2026, Africa/Cairo. **B1 SUPPORT WITHHELD; G4 ADJUSTMENT_WITHHELD. No coefficient fitted; harmonization and generalization remain unproven.** The working application and native pipeline were extended in place.',
      'The entire Phase7 directive and Phase6 execution report were read. Phase6 contracts, native/oracle bindings, all ten original L2 payloads, prior preservation snapshot and source modules were inspected and rehashed. The rejected sample and its thresholds were not repurposed.',
      '## Executed advance',
      '- Froze a separate metadata-only development study, then issued24 anonymous CMR queries. Three timing candidates yielded two prespecified pairs without consulting fire counts, cloud percentages, FRP or agreement.',
      '- Acquired12 authentic NASA HDF files /450,752,516 bytes within the900MB payload budget. Ten files are active in the final five mask/geolocation pairs; two superseded discovery geolocation files remain preserved.',
      '- Resolved the exact Aqua input-instance access problem: legacy LAADS returned401 even for known available files, while current Earthdata Cloud returned206/200 for both older exact inputs. All12 payload internal granule IDs and all5 embedded fire→geo input relationships pass independent checks. The401 was not evidence of archive absence.',
      '- Independently reconciled78,923 actual AOI center identities, raw mask/QA words, view limits and ellipsoidal5/10/20km center-bin assignments. Independently confirmed375m input/geolocation/bowtie screening.',
      '- Added a hash-checked Scientific Bridge view, real native mask-center overlays, study-date calendar and exact selected center export. Original native history, Memory Loss, source measurements, archives, holdouts and G4 remain preserved.',
      '## Frozen search and eligibility',
      'Contract: `phase7/SEARCH_CONTRACT.json`, SHA256 `'+sha(R/'SEARCH_CONTRACT.json')+'`. Parent: original Canada preregistration; Phase6 contract remains `ab874a4a4d038e30d2835829ace7a99d7276ee4fda16e9bee51207f88a95404a`.',
      'Development AOI[-118,50,-117,51], June15/16,2022UTC. Separate replication AOI[-113,53,-112,54], June22/23. All lie in the existing development region/month, before the unresolved2023 MODIS literal-code boundary. Original Portugal/California and Canada2024 model holdouts were not evaluated. Existing national inventories were previously visible, so this is not blind validation.',
      'Search six fixed collections: MYD14 C2278858993-LPCLOUD/061; MYD03 C1379841358-LAADS/6.1; VNP14 C2545314536-LPCLOUD/002; VNP03MOD C2105092427-LAADS/2; VNP14IMG C2734202914-LPCLOUD/002; VNP03IMG C2105092163-LAADS/2. Complete CMR responses, hashes, hit-count/pagination checks, start/endUTC, rings, URLs and reported sizes are cached under `data/acquisition/phase7/metadata`; `phase7/DISCOVERY.json` records every response and ranked pair.',
      'Primary timing: absolute granule-midpoint difference≤10min; sensitivity5/15min. Actual pixel matching still requires valid temporal support. View limit40°, sensitivity30/50°. No failed threshold was widened.24-response metadata cap;900MB science payload cap;≥1.2GB free-space reserve; one candidate per split. Stage2 replication375m retrieval was predeclared conditional on view/timing and exact-lineage eligibility.',
      'Rank: associated geo/375m discovery availability, maximum approximate cross-swath centerline distance, midpoint offset, estimated transfer size, then stable IDs. GRing intersection and centerline distance are geometric search proxies only: measured view zenith was null until actual arrays were acquired. Exact input compatibility and full QA applicability likewise remained unknown at metadata discovery.',
      '**Preserved correction before first CMR request:** `PRESEARCH_GEOMETRY_AMENDMENT.json` changes the approximate centerline from joining shorter to longer opposing ring-edge midpoints. The first contract is retained byte-for-byte. This repairs the search-axis geometry before outcomes; it does not alter time/view thresholds. Ranking is heuristic, not an independently validated orbit/VZA predictor.',
      '**Buffer wording correction:** the frozen prose says≥6 full days between all possible search dates; June16→June22 actually leaves five entire interveningUTC dates. The selected passes are June15 andJune23 (eight days apart). AOIs are disjoint and separated by more than50km. Independent fire-episode sampling is not established; no model or inferential performance score was fitted.',
      '## Actual selected passes and masks',
      '| Slice / date | Product | AOI centers | Water3 | Cloud4 | Land5 | Trim1 | Measured VZA | Exact geo input |',
      '|---|---|---:|---:|---:|---:|---:|---|---|']
    for split,r in a['results'].items():
        date='2022-06-15' if split=='development' else '2022-06-23'
        for product,x in r['products'].items():
            h=x['mask_counts'];text.append(f"| {split} / {date} | {product} | {x['aoi_pixel_centers']:,} | {h.get('3',0):,} | {h.get('4',0):,} | {h.get('5',0):,} | {h.get('1',0):,} | {x['view_zenith_min_degrees']:.2f}–{x['view_zenith_max_degrees']:.2f}° | {x['exact_geolocation_input_identity']} |")
    text += [
      'Development: Aqua10:40–10:45 versus VIIRS10:48–10:54UTC, midpoint offset8.5min, interval gap3min. All750m centers exceed40°; exact Aqua has just one≤40° center, which is not land/fire. Therefore the frozen primary shared-support view condition fails. A midpoint screen alone would not guarantee≤10min for every pixel: full interval endpoint separation reaches14min.',
      'Replication: Aqua09:50–09:55 versus VIIRS09:54–10:00UTC, midpoint offset4.5min. This supplies genuinely much better geometry. The ten-minute span bounds possible acquisition-time separation at granule scale, but no per-pixel oriented-footprint/time intersection has been qualified. It is not a released opportunity denominator.',
      'All five AOI/pass masks have zero classes7–9. This is a measured mask-class result, not evidence of fire-free days. Additional passes/dates and invalid/cloud regions remain outside the claim. Large non-fire samples cannot identify a fire-signal calibration. The two-pass study also fails the predeclared fitting floor of30 qualified passes across five7-day blocks, which itself would not guarantee adequate power.',
      '## Exact lineage, source QA and material findings',
      'Both exact MYD03 inputs were obtained at a CMR-derived current cloud prefix, not substituted silently. Active input links are verified against payload internal IDs and embedded fire metadata, not merely acquisition keys or filenames. `phase7/INTERNAL_PROVENANCE.json`, `PROVIDER_CONTROLS.json` and `L2_EXACT_DOWNLOAD_MANIFEST.json` contain the proof. Legacy route401 is endpoint-specific; authenticated current-cloud GET succeeded with the same private credential.',
      'Aqua fire processing version6.2.3 is distinct from collection061. VNP14 collection002 uses algorithm1.6.1/PGE2.0.4; VNP14IMG/geo production metadata remain separate fields in the exact audit. Current reprocessed L2 files have not been proven the exact ancestors of the native2022 FIRMS literal6.03/2 rows. The monthly VIIRS Type production issue remains unresolved for those archives.',
      'New exact geolocation changes AOI membership: development Aqua4369 discovery centers becomes4368 exact centers, cloud89→90, land3922→3920. Maximum same-index center displacement is13.283m (median6.678m); replication maximum8.924m (median8.641m). This demonstrates why exact input instances and half-open AOI boundaries matter. It does not quantify absolute geolocation accuracy. Original discovery results remain in `SUPPORT_AUDIT.json`; corrected exact results are a separate `EXACT_SUPPORT_AUDIT.json`.',
      'MODIS C6/C6.1 Table4 land/water, native algorithm day/night and selected contextual fields were decoded with their own definitions and independently checked by scalar arithmetic. They are not the375m input-quality bit layout. Full source QA policy is not declared complete merely by decoding fields.',
      'For375mC2, the exact guide supplies input-quality bits0–6 and residual-bowtie bit22. Independent raw reads find46,653 centers, no nonzero geolocation flags, non-nominal inputs or residual bowtie flags;45,039 mask-land centers pass that screen and the40° view limit. These are QA-screened centers, not matched exposure area or45,039 qualified opportunities. Two native cloud centers are retained explicitly.',
      'The C2 VNP14 CMR record still links a C1 guide/filespec. Their applicability to the exact750mC2 algorithm QA has not been established. The375m bits were never borrowed. Pixel centers, GRings, grid-cell bounds and nominal resolution do not establish actual oriented IFOV footprints. No shared area was fabricated by rasterizing point spacing.',
      '## Scientific decision and independent validation',
      '| Estimand / stage | Executed result |',
      '|---|---|',
      '| B0 native detections and source-specific occupied cell-days | Preserved; no correction, re-ingestion or baseline substitution |',
      '| Physical equal-area grid cells | Existing WGS84 LAEA60N/100W origin0;5/10/20km independent center-bin checks;10km cell is100km², not observed/burned area |',
      '| B1 qualified matched opportunities / area | **null / UNKNOWN**, never zero; development fails view policy, replication footprint and full QA qualification incomplete |',
      '| B2 750m continuity | Actual750m and375m masks decoded; hypothesis inconclusive on unqualified support and no positive fire signal |',
      '| B3 FRP MW correction | NOT FITTED; no coefficient or hotspot-count conversion |',
      '| B4 harmonized historical calendar / generalization | NOT RELEASED / NOT TESTED |',
      '| G4 | ADJUSTMENT_WITHHELD; original gates and signatures unchanged |',
      '`EXACT_INDEPENDENT_VALIDATION.json` reopens raw HDF arrays in113-row blocks, separately counts native classes/QA, checks every mapped tuple and reprojects with independent ellipsoidal EPSG9820 equations against production PROJ at5/10/20km. Five checks PASS. `QUALIFICATION_SENSITIVITY.json` separately verifies375m QA and measures geolocation-instance displacement. `INTERNAL_PROVENANCE.json` independently checks12 internal IDs /5 exact links. These are independent software paths, not independent human review.',
      '**Not executed:** independently qualified physical footprint intersection, a valid shared-area denominator, a fitted candidate, baseline-vs-candidate predictive error, model uncertainty intervals, holdout skill or reviewer approval. There is no measurable harmonization improvement to claim. The advance is authentic near-nadir data, resolved lineage, source-specific QA and falsifiable support rejection—not success by interface alone.',
      'Support representation retains six possible scientific states. Current mapped support is UNKNOWN_SUPPORT or diagnostic CLOUD_OR_INVALID at native centers; raw mask classes remain separate. VALID_SHARED_SUPPORT, VALID_SINGLE_SENSOR_SUPPORT and QUALIFIED_OBSERVED_NONDETECTION are not asserted as footprint-qualified area. No positive mask pixels occur in this sample; raw native positive records remain available through preserved releases.',
      '## Product implementation',
      'Existing Bridge laboratory → **Scientific Bridge · new observation search** opens the compact six-step method/result view. Inspect either selectedUTC pass and native product on the original MapLibre map. Neutral small dots show actual center locations; purple marks native cloud codes, dark marks invalid/trim codes. Dashed gray study bounds are explicitly not observed footprints. No success color, corrected scale, filled missing history or inferred fire-free state is used.',
      'The observation study calendar exposes only acquiredJune15/23 and disables unacquiredJune16/22. Product/date selection, full center identities and selected CSV are hash-bound and reconciled. Export includes exact raw mask/QA, coordinates, granule acquisition interval, source identity, evidence hashes, unknown denominator and withheld gate. Acquisition intervals are not mislabeled exact pixel timestamps. Native source cards/calendar/export return intact through Native history. Stale native-year selectors are hidden during research mode; the skip link points to the active study calendar.',
      'Rendered review corrected overly dense gray points and a stale native-year control. A follow-up performance run detected missing rendered masks. The invalid nested zoom paint expression was corrected, and research framing was also guarded against a late native-load camera race identified during investigation. The final implementation uses a valid constant conditional point radius. A delayed native-load test verifies the actual rendered point layer remains in the frozen AOI. An intermediate full-suite run was interrupted while correcting this regression; it is not counted as a passing run.',
      '## Executed tests and measurements',
      'Python unittest discovery: **40/40 PASS**. TypeScript/Vite production build: PASS; inherited large MapLibre chunk advisory remains. Final full browser suite: **'+str(tests['expected'])+'/'+str(tests['expected'])+' PASS**, '+f"{tests['duration']/1000:.3f}"+'s; no skipped, flaky or unexpected results. Original full95-test run and intermediate12/6/7-test follow-ups are retained separately. Final browser coverage includes delayed native delivery, rendered masks, checksum withholding, selected CSV/source/date identity, all inherited scientific/native product contracts, keyboard use and widths1440/390/320.',
      'Five-mask warm read-only replay: '+f"{memory['elapsed_seconds']:.3f}"+'s; OS peak Python working set '+f"{memory['peak_working_set_bytes']/1e6:.2f}"+'MB. Semantic mask/grid/view results reproduced without rewriting science artifacts. This excludes acquisition time, browser/GPU and full-country ETL.',
      'Three fresh Chromium SwiftShader contexts at1440×900: median study readiness '+str(median(v['runs'],'readyMs'))+'ms;46,653-center binding '+str(median(v['runs'],'bindMs'))+'ms; geographic/point rendering '+str(median(v['runs'],'geographicMs'))+'ms. Median page heap snapshot '+f"{median(v['runs'],'heap_snapshot_bytes')/1e6:.2f}"+'MB; excludes workers/GPU and is not a peak. This is a much larger workload than Phase6’s77 positive points, so no direct speedup claim. Resource sizes and warm source-switch durations are in `VISUAL_AND_PERFORMANCE.json`.',
      '| Viewport | Unobscured map / viewport estimate | Overflow | Rendered375m centers |',
      '|---|---:|---|---:|']
    for capture in v['captures']:
        x=capture['replication'];text.append(f"| {capture['width']}×900 | {100*x['unobscured_fraction_of_viewport']:.1f}% | {'none' if x['bodyWidth']==capture['width'] else 'FAIL'} | {x['renderedMaskFeatures']:,} |")
    text += ['These are DOM overlay-area estimates, not perceptual salience measurements; the70% unobscured target is not achieved on narrow mobile. All panels dismiss; source/date controls and attribution remain visible. Final desktop/mobile screenshots were opened and inspected, not only saved. Screenshots: `screenshots/phase7-result-{1440,390,320}.png`, `phase7-replication375-{1440,390,320}.png`, `phase7-rejected750-{1440,390,320}.png`. Initial captures/measurements remain separately retained.',
      '## Preservation and security',
      f"Snapshot `data/backups/phase7-before.zip`:899 files, SHA256 `{p['snapshot_sha256']}`. {p['inherited_unchanged']} inherited files byte-unchanged; only four inherited UI files changed (listed below).28 original/current archive, native/oracle database and L2 payload hashes pass; both Phase7 research versions’ artifact hashes pass. Original G4/protocol/release artifacts and Phase6 source/science reports are preserved.",
      'Both chat-exposed token revocations are USER-ATTESTED, not independently verified by API. Authenticated requests used only the new operator-supplied private file outside the project. Cookies stayed in memory. No token, account identifier, credential hash or signed redirect query was exported. The user-owned private file remains outside the project. Project text scan found zero credential occurrences; exact scan scope is recorded in `SECRET_HANDLING.json`.',
      'Local BUILD authorization remains USER-ATTESTED. Existing unresolved global-award/reuse eligibility entries remain unresolved; no NASA/GOT approval or NASA endorsement is fabricated.',
      '## Exact code changes',
      'Modified inherited files:']
    text += ['- `'+n+'`' for n in p['modified']]
    text += ['New source, verification and test files:']+['- `'+n+'`' for n in new_sources]
    text += ['All new report/public artifact paths are enumerated in `phase7/PRESERVATION.json`. The original immutable source archives were never modified. Active research pointer: `public/data/phase7/index.json`; both content-versioned research folders remain available.',
      '## Acquired file identities',
      '| Split / product | Actual preserved filename | Bytes | SHA256 |','|---|---|---:|---|']
    for x in m['receipts']:text.append(f"| {x['split']} / {x['product']} | `{Path(x['file']).name}` | {x['bytes']:,} | `{x['sha256']}` |")
    text += ['Full paths/original provider URLs and redacted receipts: `phase7/L2_EXACT_DOWNLOAD_MANIFEST.json`. New exact MYD03 entries take precedence only in the separately versioned exact audit; discovery geolocation files and first audits remain intact.',
      '## Key scientific artifact hashes','| Artifact | SHA256 |','|---|---|']
    for name in ['SEARCH_CONTRACT.json','DISCOVERY.json','L2_EXACT_DOWNLOAD_MANIFEST.json','EXACT_SUPPORT_AUDIT.json','EXACT_MASK_CENTERS.json','EXACT_INDEPENDENT_VALIDATION.json','QUALIFICATION_SENSITIVITY.json','INTERNAL_PROVENANCE.json']:
        text.append('| '+name+' | `'+sha(R/name)+'` |')
    text += ['## Official references and limits',
      '- [MODIS C6/C6.1 guide](https://lpdaac.usgs.gov/documents/1005/MOD14_User_Guide_V61.pdf), Table4 and§8.4.6: source-specific QA and approximate scan-dependent dimensions. Nominal pixel area is not a qualified oriented overlap polygon.',
      '- [NASA 375 m C2 guide v1.2](https://ladsweb.modaps.eosdis.nasa.gov/archive/Document%20Archive/Science%20Data%20Product%20Documentation/VIIRS_C2_AF-375m_User_Guide_1.2.pdf), Table2: exact375m input/bowtie fields. Its§6.1 monthly Type issue is not resolved by literal row version2.',
      '- [CMR-linked VIIRS guide](https://lpdaac.usgs.gov/documents/427/VNP14_User_Guide_V1.pdf) explicitly describesC1; [750m ATBD](https://lpdaac.usgs.gov/documents/133/VNP14_ATBD.pdf) is2017. They motivate methods; they do not certify currentC2 bit applicability.',
      '- [NASA FireESDR](https://viirsland.gsfc.nasa.gov/Products/NASA/FireESDR.html) motivates750m continuity; independent algorithms and resolution differences do not establish numerical interchangeability.',
      '- [Official EDL workflow](https://ladsweb.modaps.eosdis.nasa.gov/learn/download-files-using-edl-tokens/): private bearer header, redirects and cookies. Actual cloud-vs-legacy controls above are narrower evidence than a general access claim.',
      'Four official PDFs were acquired and hashed in `phase7/REFERENCES.json`. Phase6’s reviewed Li2018, Zheng2026 and Sofiev2026 FRP methods remain technical context; no coefficient, random split or FRP-to-count conversion was adopted. No new literature-based validation claim was made.',
      '## Reproduce and demonstrate',
      'Use the existing venv and app; no restart/re-ingestion. New cached acquisition receipts and all scientific artifacts are immutable. Auth scripts require only a private external token path and prior revocation confirmation; never pass token text. Execute `phase7_contract.py`, cached `phase7_discovery.py`; acquisition scripts only when inputs are absent and authorization is current. `phase7_memory.py` replays five final masks read-only; tests verify both report versions. Fresh isolated recalculation can rerun the production/oracle paths; elapsed timings are machine-specific, so byte identity of runtime-containing reports is not promised. Publication and gate changes are separate; no deployment/submission occurred.',
      'Judge demonstration: open Canada → Bridge laboratory → Scientific Bridge. Show24 metadata queries and two frozen candidates. Inspect June15’s view rejection, then June23’s 750m and 375m masks. Point out exact input provenance,45,039 375m screened land centers, two cloud centers, unknown common support and disabled unacquired dates. Export the exact displayed centers. Return to native history; demonstrate unchanged Memory Loss and source measurements. End with the withheld gate rather than implying a completed bridge.',
      '**Next meaningful scientific milestone:** independently qualify oriented, source-specific footprint/time support for the exact near-nadir pair and resolve750mC2 QA applicability from current authoritative documentation or source. Then preregister a larger metadata-selected development sample with an actually qualified positive fire signal and blocked replication. Keep this sample’s negative findings, original holdouts and G4 sealed; do not loosen thresholds or select a replacement because its fires appear to agree.',
      '**Submission-ready claim:** EmberGuard preserves native historical fire evidence and now tests prospective continuity experiments against authentic L2 masks with exact lineage and independent recounts. It can reject unsupported comparisons. It has not calibrated MODIS to VIIRS or recovered unobserved fire history.']
    content=('\n\n'.join(text)+'\n').replace('|\n\n|','|\n|')
    fragments=re.split(r'(`[^`]*`|\[[^\]]*\]\([^)]*\))',content)
    for i in range(0,len(fragments),2):
        part=fragments[i]
        for word in ['Phase','June','Table','classes','Water','Cloud','Land','Trim','Canada','All','all','issued','Acquired','acquired','reconciled','confirmed','the','For','for','than','version','algorithm','collection','against','Aqua','VIIRS','find','of','at','across','actual','exact','current','describes','is','Show','resolve','limit','sensitivity','five','Li','Zheng','Sofiev']:
            part=re.sub(r'\b'+word+r'(?=\d)',word+' ',part)
        part=re.sub(r'(\d)(km|MB|GB|ms|min|m|s)\b',r'\1 \2',part)
        part=part.replace('375mC2','375 m C2').replace('2022UTC','2022 UTC').replace('interveningUTC','intervening UTC').replace('selectedUTC','selected UTC').replace('dayUTC','day UTC').replace('7day','7-day').replace('750mC2','750 m C2').replace('and§','and §').replace('Its§','Its §').replace('one≤','one ≤')
        fragments[i]=part
    (ROOT/'reports/PHASE7_BRIDGE_EXECUTION.md').write_text(''.join(fragments),encoding='utf-8')
    print(json.dumps({'report':'reports/PHASE7_BRIDGE_EXECUTION.md','words':len(' '.join(text).split()),'scientific_state':a['state'],'tests':tests['expected']}))

if __name__=='__main__':run()
